function authHeader(){const id=process.env.RAZORPAY_KEY_ID,secret=process.env.RAZORPAY_KEY_SECRET;if(!id||!secret)throw new Error('RAZORPAY_NOT_CONFIGURED');return `Basic ${Buffer.from(`${id}:${secret}`).toString('base64')}`;}
export async function createRazorpayOrder(amountInPaise:number,receipt:string,notes:Record<string,string>){const r=await fetch('https://api.razorpay.com/v1/orders',{method:'POST',headers:{Authorization:authHeader(),'Content-Type':'application/json'},body:JSON.stringify({amount:amountInPaise,currency:'INR',receipt,notes})});if(!r.ok)throw new Error('RAZORPAY_ORDER_FAILED');return r.json() as Promise<{id:string;amount:number;currency:string;status:string}>;}
export async function fetchRazorpayPayment(paymentId:string){const r=await fetch(`https://api.razorpay.com/v1/payments/${encodeURIComponent(paymentId)}`,{headers:{Authorization:authHeader()},cache:'no-store'});if(!r.ok)throw new Error('RAZORPAY_PAYMENT_LOOKUP_FAILED');return r.json() as Promise<{id:string;order_id:string;amount:number;currency:string;status:string}>;}
